use std::sync::Mutex;

static X: Mutex<i32> = Mutex::new(0);
static Y: Mutex<i32> = Mutex::new(0);

fn worker_a() {
    let mut x = X.lock().unwrap();
    let mut y = Y.lock().unwrap();
    *x += 1;
    *y += 1;
}

fn worker_b() {
    let mut x = X.lock().unwrap();
    let mut y = Y.lock().unwrap();
    *y -= 1;
    *x -= 1;
}
